import type { Register } from 'claude-code'

// Masks secret-shaped values in every tool's output before the model, the transcript
// or the terminal row sees them: a hook's own `{ result }` is what core records.
// Fails closed, like guard.sh: core skips a hook that throws or outruns its budget and
// would pass the output unmasked, so the `.catch` below withholds the output instead.
// Best-effort pattern list, not a guarantee. The model's own tool_use input is recorded before this runs,
// so input is never redacted here.

// Spelled in two halves so no file of this plugin holds the mark: the write-back guard
// below then needs no exemption for them.
export const MARK = '[RED' + 'ACTED]'
// Every repeat that can run into a failing match is bounded ({0,64}, {1,512}, {0,8192}):
// unbounded, a crafted output (one long word full of "token", thousands of `-eyJ` or
// unterminated BEGIN lines) takes time quadratic in its size, outruns the hook budget and
// would leak the rest of that output. The speed test in redact.test.ts pins this.
const NAME = String.raw`\w{0,64}(?:token|secret|password|passwd|api[_-]?key|private[_-]?key|access[_-]?key|credential)\w{0,64}`
// An unquoted value ends at whitespace, quotes and code punctuation, so `fn(name=value), y`
// keeps its `), y` and a query string keeps its `&next=1`. No `[` or `]` either, so no rule
// re-matches the mark: every rule is idempotent on its own output.
const STOP = String.raw`\s'"\`,;&<>()[\]{}`
const VAL = String.raw`[^${STOP}]+`
const END = String.raw`(?![^${STOP}])`
// Unquoted values that read as code and stay: a `$` reference or shell default (`${X:-}`,
// `${X:-$Y}`), a call or index (`getToken(`, `os.environ[`), a keyword, type or literal
// (`await`, `string`, `1000`), a dotted path (`self.token`; a dotted literal password leaks,
// the price of this one), or the name itself (Python's `f(token=token)`). Anything else is
// masked: a miss masks. `\2` is the assign rule's NAME group: CODE only works inside it.
const CODE = String.raw`(?!-?\$|[\w.]+[(\[]|(?:await|new|string|number|boolean|bool|str|int|bytes|any|unknown|undefined|none|nil|true|false|null|\d+|[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+|\2|-)${END})`
// ordered: whole-value shapes first, so the later rules see the mark and leave it
const RULES: [RegExp, string][] = [
  // with no END line (output cut short by head or a Read limit), the whole-line base64 body
  // after BEGIN, raw, `cat -n` numbered or JSON-escaped; a prose line stops it, and a BEGIN
  // line with no body (a doc naming the format) is left alone
  [/-----BEGIN [A-Z ]*PRIVATE KEY-----(?:[\s\S]{0,8192}?-----END [A-Z ]*PRIVATE KEY-----|(?:(?:\r?\n|\\n)[ \t]*(?:\d+\t)?[A-Za-z0-9+/=]+(?=[\r\n\\]|$))+)/g, MARK],
  // JS copy of scripts/git-hooks/lib/secret-content.ere's vendor shapes (plus hf_, ya29.): keep in sync
  [/\b(?:sk-[\w-]{20,}|gh[pousr]_\w{36,}|github_pat_\w{20,}|(?:AKIA|ASIA)[0-9A-Z]{16}|xox[abprs]-[\w-]{10,}|AIza[\w-]{35}|[sr]k_(?:live|test)_[0-9A-Za-z]{24,}|glpat-[\w-]{20,}|npm_[A-Za-z0-9]{36}|dckr_pat_[\w-]{20,}|SG\.[\w-]{20,}\.[\w-]{20,}|hf_[A-Za-z0-9]{30,}|ya29\.[\w-]{20,}|eyJ[\w-]{1,512}\.[\w-]+\.[\w-]+)/g, MARK],
  [/(bearer[ \t]+)[\w.~+/-]+=*/gi, `$1${MARK}`], // RFC 6750 token chars
  [/(:\/\/[^:\/\s@]+:)(?!\$)[^\s@\/]+@/g, `$1${MARK}@`],
  [new RegExp(String.raw`(--(?:password|token|api-key|secret)[ \t]+)(?![$-])${VAL}`, 'gi'), `$1${MARK}`],
  // `NAME=v`, `name: v`, `"name": "v"`: a quoted value up to its closing quote (or the line's
  // end), unless empty or a `$` reference; an unquoted one unless CODE says it is code
  [new RegExp(String.raw`(\b(${NAME})["']?[ \t]*[=:][ \t]*)(?:(["'])(?!\$)(?:(?!\3)[^\n])+(\3?)|${CODE}${VAL})`, 'gi'), `$1$3${MARK}$4`],
]

export const redact = (s: string) => RULES.reduce((acc, [re, to]) => acc.replace(re, to), s)

const walk = (v: unknown, hit: { n: number }): unknown => {
  if (typeof v === 'string') { const r = redact(v); if (r !== v) hit.n++; return r }
  if (Array.isArray(v)) return v.map(x => walk(x, hit))
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, walk(x, hit)]))
  return v
}

// The input fields whose text lands in a file or runs. Bash is checked whole: a write that
// is no file write (`gh secret set --body`, `curl -d`) has no shape to tell it apart.
const WRITES: Record<string, string[]> = { Write: ['content'], Edit: ['old_string', 'new_string'], NotebookEdit: ['new_source'], Bash: ['command'] }

export const register: Register = (on) => {
  on('tool.call', async (_, e, next) => {
    // Write-back guard: the mark stands in for a value the model never saw, so as old text
    // it can't match and as new text it would overwrite the real value. Writers' content
    // only: quoting the mark to the person (SendUserMessage) or in a description is fine.
    if (WRITES[e.tool]?.some(k => String((e as any)[k] ?? '').includes(MARK))) {
      return { deny: `input contains ${MARK}, the redact plugin's stand-in for a masked value; the real value is still in place, so old text with it can't match and new text with it would overwrite the real value. Edit around the masked span, or ask the user.` }
    }
    const r = await next(e)
    if (r.deny) return r
    if (r.isError) {
      // isError is core's alone: a hook's { result } would turn the error into a success.
      // A deny carries the text to the model as an error result, so errors stay errors.
      // `text` can be absent; `result` then holds the stored error text.
      const raw = r.text ?? (typeof r.result === 'string' ? r.result : undefined)
      const text = raw === undefined ? undefined : redact(raw)
      return text === undefined || text === raw ? r : { deny: text }
    }
    const hit = { n: 0 }
    const result = walk(r.result, hit)
    // nothing masked: hand back core's own object so it reuses its messages (`ref`)
    return hit.n ? { result: result as any, context: r.context } : r
  }).catch(async (_, e, next) => ({
    // The hook threw or outran its budget: withhold rather than pass the output unmasked.
    // No work here, the grace is 1 s. `called`: the tool ran, so retrying repeats it.
    deny: next.called
      ? `${e.tool} ran, but its output is withheld: the redact plugin failed to mask it (${next.error.kind}). Narrow the output (head, grep, a Read limit) and retry.`
      : `${e.tool} did not run: the redact plugin failed before it (${next.error.kind}).`,
  }))
}

